snippets.snippet:
views {
  view backend-focus {
    include *
    style * { color muted }
    style cloud.backend.* { color primary }
  }
}

deployment {
  vm app_vm {
    api_1 = instanceOf cloud.api
    api_2 = instanceOf cloud.api
  }
}

views {
  view backend-related of cloud.backend {
    include -> cloud.backend ->
    include cloud.backend._
  }
}

views {
  view backend-overview of cloud.backend {
    include *
  }

  view detail extends backend-overview {
    include api
    include -> cloud.backend
  }
}

global {
  predicateGroup core-services {
    include cloud.* where kind is service
    exclude * where tag is #deprecated
  }
}

views {
  view core-services-styled {
    global predicate core-services
    style * { color muted }
  }

  view core-services-with-extra {
    global predicate core-services
    include cloud.gateway
  }
}

dynamic view checkout-flow {
  customer
    -> frontend "checkout"
    -> api "submit order" {
      technology "HTTPS"
      navigateTo payment-detail
    }

  parallel {
    api -> payments "charge"
    api -> inventory "reserve"
    api -> notifications "notify"
  }
}

specification {
  element app
  element db
  deploymentNode env
  deploymentNode region
  deploymentNode vm
  tag next
  tag gamma
  tag missing
}

model {
  frontend = app {
    #next
    -> db "reads"
  }
  db = db
}

deployment {
  prod = env {
    eu = region {
      web = vm {
        frontend = instanceOf frontend {
          #gamma
        }
      }
      data = vm {
        db = instanceOf db
      }
    }
  }
}

views {
  deployment view rel_only_next {
    include * -> * where source.tag is #next
  }

  deployment view rel_only_gamma {
    include * -> * where source.tag is #gamma
  }

  deployment view rel_only_missing {
    include * -> * where source.tag is #missing
  }
}

model {
  extend cloud.api {
    metadata {
      port "9090"
      region "us-east-1"
    }
    health = component "Health Check"
  }
}

views {
  deployment view prod_nodes {
    include prod.**
    style * { color red }
  }
}

model {
  api = service 'API' {
    #critical
    technology 'Node.js'
  }
}

global {
  styleGroup darkish {
    style * { color muted }
  }
}

views {
